import React from 'react';
import './tools.css';

const tools = [
  {
    name: 'Tool A',
    description: 'This is a description for Tool A. It helps with pattern analysis and design.'
  },
  {
    name: 'Tool B',
    description: 'This tool is used to generate complex patterns and templates.'
  },
  {
    name: 'Tool C',
    description: 'Tool C provides real-time pattern validation and corrections.'
  }
];

const PatternTool = () => {
  return (
    <div className="pattern-tool-container">
      <h1 className="pattern-tool-title">Pattern Tools</h1>
      {tools.map((tool, index) => (
        <div key={index} className="tool-card">
          <h2 className="tool-name">{tool.name}</h2>
          <p className="tool-description">{tool.description}</p>
        </div>
      ))}
    </div>
  );
};

export default PatternTool;
